-- Source of Sales reference hierarchy seeded from SATO_Sales_Master_Template_buttons.xlsx.
-- Generated on 2026-05-29 after reviewing the workbook tab by tab.
-- Codes are authoritative. Different names/aliases with the same code are treated as the same entity.
-- Brick hierarchy is derived from Block_Master -> Area_Master -> Region_Master.
-- Sheet1 is intentionally not seeded because Brick_Master is the named official brick tab.

create table if not exists public.source_of_sales_regions (
  region_code text primary key,
  region_name text not null,
  normalized_region_name text not null,
  description text not null default '',
  active boolean not null default true,
  effective_from date null,
  effective_to date null,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Region_Master',
  source_row_number integer null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_regions_code_not_blank check (btrim(region_code) <> ''),
  constraint source_of_sales_regions_name_not_blank check (btrim(region_name) <> ''),
  constraint source_of_sales_regions_effective_range check (effective_to is null or effective_from is null or effective_to >= effective_from)
);
create table if not exists public.source_of_sales_areas (
  area_code text primary key,
  region_code text not null references public.source_of_sales_regions(region_code) on update cascade on delete restrict,
  area_name text not null,
  normalized_area_name text not null,
  description text not null default '',
  active boolean not null default true,
  effective_from date null,
  effective_to date null,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Area_Master',
  source_row_number integer null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_areas_code_not_blank check (btrim(area_code) <> ''),
  constraint source_of_sales_areas_name_not_blank check (btrim(area_name) <> ''),
  constraint source_of_sales_areas_effective_range check (effective_to is null or effective_from is null or effective_to >= effective_from),
  constraint source_of_sales_areas_area_region_key unique (area_code, region_code)
);
create table if not exists public.source_of_sales_blocks (
  block_code text primary key,
  area_code text not null,
  region_code text not null,
  description text not null default '',
  normalized_description text not null default '',
  active boolean not null default true,
  effective_from date null,
  effective_to date null,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Block_Master',
  source_row_number integer null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_blocks_code_not_blank check (btrim(block_code) <> ''),
  constraint source_of_sales_blocks_effective_range check (effective_to is null or effective_from is null or effective_to >= effective_from),
  constraint source_of_sales_blocks_area_region_fk foreign key (area_code, region_code)
    references public.source_of_sales_areas(area_code, region_code) on update cascade on delete restrict,
  constraint source_of_sales_blocks_block_area_region_key unique (block_code, area_code, region_code)
);
create table if not exists public.source_of_sales_bricks (
  brick_id text primary key,
  brick_name text not null,
  normalized_brick_name text not null,
  block_code text not null,
  area_code text not null,
  region_code text not null,
  source_area_code text null,
  source_region_code text null,
  description text not null default '',
  normalized_description text not null default '',
  active boolean not null default true,
  effective_from date null,
  effective_to date null,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Brick_Master',
  source_row_number integer null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_bricks_id_not_blank check (btrim(brick_id) <> ''),
  constraint source_of_sales_bricks_name_not_blank check (btrim(brick_name) <> ''),
  constraint source_of_sales_bricks_effective_range check (effective_to is null or effective_from is null or effective_to >= effective_from),
  constraint source_of_sales_bricks_block_hierarchy_fk foreign key (block_code, area_code, region_code)
    references public.source_of_sales_blocks(block_code, area_code, region_code) on update cascade on delete restrict
);
create table if not exists public.source_of_sales_product_aliases (
  id bigint generated by default as identity primary key,
  alias text not null,
  normalized_alias text not null,
  product_code text not null references public.source_of_sales_products(product_code) on update cascade on delete restrict,
  source_labels text[] not null default '{}'::text[],
  source_row_numbers integer[] not null default '{}'::integer[],
  active boolean not null default true,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Product_Alias',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_product_aliases_alias_not_blank check (btrim(alias) <> ''),
  constraint source_of_sales_product_aliases_normalized_alias_not_blank check (btrim(normalized_alias) <> '')
);
create table if not exists public.source_of_sales_region_aliases (
  id bigint generated by default as identity primary key,
  region_code text not null references public.source_of_sales_regions(region_code) on update cascade on delete restrict,
  alias text not null,
  normalized_alias text not null,
  source_labels text[] not null default '{}'::text[],
  source_row_numbers integer[] not null default '{}'::integer[],
  active boolean not null default true,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Region_Master',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_region_aliases_alias_not_blank check (btrim(alias) <> ''),
  constraint source_of_sales_region_aliases_normalized_alias_not_blank check (btrim(normalized_alias) <> '')
);
create table if not exists public.source_of_sales_area_aliases (
  id bigint generated by default as identity primary key,
  area_code text not null,
  region_code text not null,
  alias text not null,
  normalized_alias text not null,
  source_labels text[] not null default '{}'::text[],
  source_row_numbers integer[] not null default '{}'::integer[],
  active boolean not null default true,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Area_Master',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_area_aliases_area_region_fk foreign key (area_code, region_code)
    references public.source_of_sales_areas(area_code, region_code) on update cascade on delete restrict,
  constraint source_of_sales_area_aliases_alias_not_blank check (btrim(alias) <> ''),
  constraint source_of_sales_area_aliases_normalized_alias_not_blank check (btrim(normalized_alias) <> '')
);
create table if not exists public.source_of_sales_territory_aliases (
  id bigint generated by default as identity primary key,
  alias text not null,
  normalized_alias text not null,
  target_type text not null default 'brick',
  target_code text not null,
  notes text not null default '',
  source_row_numbers integer[] not null default '{}'::integer[],
  active boolean not null default true,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null default 'Territory_Alias',
  source_row_number integer null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint source_of_sales_territory_aliases_alias_not_blank check (btrim(alias) <> ''),
  constraint source_of_sales_territory_aliases_target_code_not_blank check (btrim(target_code) <> ''),
  constraint source_of_sales_territory_aliases_target_type_check check (target_type in ('region', 'area', 'block', 'brick'))
);
create table if not exists public.source_of_sales_reference_issues (
  id bigint generated by default as identity primary key,
  source_file text not null default 'SATO_Sales_Master_Template_buttons.xlsx',
  source_sheet text not null,
  source_row_number integer null,
  reference_key text not null,
  issue_code text not null,
  issue_message text not null,
  raw_payload jsonb not null default '{}'::jsonb,
  status text not null default 'documented',
  created_at timestamptz not null default now(),
  constraint source_of_sales_reference_issues_status_check check (status in ('documented', 'resolved', 'ignored'))
);
