insert into public.source_of_sales_area_regions (
  area_code,
  area_name,
  normalized_area_name,
  region_code,
  region_name,
  normalized_region_name,
  source_file,
  source_sheet,
  source_row_number,
  active
)
select
  area.area_code,
  area.area_name,
  area.normalized_area_name,
  region.region_code,
  region.region_name,
  region.normalized_region_name,
  area.source_file,
  area.source_sheet,
  area.source_row_number,
  area.active and region.active
from public.source_of_sales_areas area
join public.source_of_sales_regions region on region.region_code = area.region_code
on conflict (area_code) do update set
  area_name = excluded.area_name,
  normalized_area_name = excluded.normalized_area_name,
  region_code = excluded.region_code,
  region_name = excluded.region_name,
  normalized_region_name = excluded.normalized_region_name,
  source_file = excluded.source_file,
  source_sheet = excluded.source_sheet,
  source_row_number = excluded.source_row_number,
  active = excluded.active,
  updated_at = now();
