  normalized_region_name,
  array['Region_Master']::text[],
  array_remove(array[source_row_number], null)::integer[],
  active,
  source_file,
  source_sheet
from public.source_of_sales_regions
union all
select
  region_code,
  description,
  lower(regexp_replace(btrim(description), '\s+', ' ', 'g')),
  array['Region_Master description']::text[],
  array_remove(array[source_row_number], null)::integer[],
  active,
  source_file,
  source_sheet
from public.source_of_sales_regions
where btrim(description) <> ''
  and lower(regexp_replace(btrim(description), '\s+', ' ', 'g')) <> normalized_region_name
on conflict (region_code, normalized_alias) do update set
  alias = excluded.alias,
  source_labels = excluded.source_labels,
  source_row_numbers = excluded.source_row_numbers,
  active = excluded.active,
  source_file = excluded.source_file,
  source_sheet = excluded.source_sheet,
  updated_at = now();
insert into public.source_of_sales_area_aliases (
  area_code,
  region_code,
  alias,
  normalized_alias,
  source_labels,
  source_row_numbers,
  active,
  source_file,
  source_sheet
)
select
  area_code,
  region_code,
  area_name,
  normalized_area_name,
  array['Area_Master']::text[],
  array_remove(array[source_row_number], null)::integer[],
  active,
  source_file,
  source_sheet
from public.source_of_sales_areas
on conflict (area_code, normalized_alias) do update set
  region_code = excluded.region_code,
  alias = excluded.alias,
  source_labels = excluded.source_labels,
  source_row_numbers = excluded.source_row_numbers,
  active = excluded.active,
  source_file = excluded.source_file,
  source_sheet = excluded.source_sheet,
  updated_at = now();
